class OrderAdapter {
public:
  OrderAdapter(zmq::context_t &ctx, const std::string &endpoint)
      : push_(ctx, zmq::socket_type::push) { push_.connect(endpoint); }
  void place(const Order &o) {
    auto body = encode(o);
    zmq::message_t frame(body.data(), body.size());
    push_.send(frame, zmq::send_flags::none);   // fire and forget
  }
private:
  zmq::socket_t push_;
};
